<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,dateTime,exportCsv,matches,outcomeLabel,pagination,useActions,type Row} from './api';import AppIcon from './AppIcon.vue';import PagePanel from './PagePanel.vue';
const props=defineProps<{mode:'audit'|'alerts'}>();const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),search=ref(''),kind=ref('SQL_READ'),outcome=ref('all'),from=ref(''),to=ref(''),detail=ref<Row|null>(null),alertStatus=ref(''),severity=ref(''),live=ref<Row|null>(null);const {busy,perform}=useActions();let sequence=0;
const actions:Record<string,string>={SQL_READ:'SQL 读取',LOGIN:'登录',PASSWORD_CHANGED:'修改密码',PASSWORD_RESET:'重置密码',USER_CREATED:'创建用户',USER_DISABLED:'停用用户',USER_ENABLED:'启用用户',SOURCE_CREATED:'创建数据源',SOURCE_UPDATED:'编辑数据源',SOURCE_ENABLED:'启用数据源',SOURCE_DISABLED:'停用数据源',SOURCE_CONNECTION_TEST:'数据源连接测试',TABLE_ALLOWED:'授权数据表',TABLE_REVOKED:'撤销表授权',COLUMN_ALLOWED:'授权字段',COLUMN_REVOKED:'撤销字段授权',APPROVAL_REQUESTED:'发起申请',APPROVAL_APPROVED:'审批通过',APPROVAL_REJECTED:'审批拒绝',AGENT_TOKEN_CREATED:'创建 Agent 凭据',AGENT_TOKEN_REVOKED:'撤销 Agent 凭据',SQL_POLICY_CREATED:'创建策略',SQL_POLICY_VERSION_CREATED:'保存规则版本',SQL_POLICY_PUBLISHED:'发布策略配置',SQL_POLICY_DISABLED:'停用策略配置',WORKFLOW_DESIGN_CREATED:'创建流程设计',WORKFLOW_DESIGN_REVISION:'保存流程版本',WORKFLOW_DESIGN_PUBLISHED:'发布流程配置',ALERT_ACKNOWLEDGED:'确认告警',ALERT_RESOLVED:'解决告警',MCP_REQUEST:'MCP 请求'};
const alertLabels:Record<string,string>={OPEN:'待处理',ACKNOWLEDGED:'已确认',RESOLVED:'已解决',LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'严重',SQL_READ_DENIED:'读取请求被拒绝',SQL_READ_ERROR:'读取执行失败',SQL_READ_FAILED:'读取执行失败'};
const filtered=computed(()=>rows.value.filter(row=>{if(!matches(row,search.value,props.mode==='alerts'?['actor','resource','detail','eventType']:['actor_username','resource_id','action','detail']))return false;if(props.mode==='alerts')return true;const date=dateTime(row.event_time).slice(0,10);return (!from.value||date>=from.value)&&(!to.value||date<=to.value)&&(outcome.value==='all'||(outcome.value==='failed'?['ERROR','FAILED'].includes(row.outcome):row.outcome===outcome.value))}));
async function refresh(){const current=++sequence;loading.value=true;error.value='';try{if(props.mode==='alerts'){const data=await api<Row[]>('/api/security-alerts?'+new URLSearchParams({status:alertStatus.value,severity:severity.value}));if(current===sequence)rows.value=data}else{const [data,metrics]=await Promise.all([api<Row[]>('/api/audit?action='+kind.value),api<Row>('/api/operations/live')]);if(current===sequence){rows.value=data;live.value=metrics}}}catch(e){if(current===sequence)error.value=(e as Error).message}finally{if(current===sequence)loading.value=false}}
async function decide(row:Row,action:'acknowledge'|'resolve'){if(await perform('/api/security-alerts/'+row.id+'/'+action,{},'POST',action==='acknowledge'?'告警已确认':'告警已解决'))await refresh()}
function exportRows(){exportCsv('DataGuard-'+(kind.value?'SQL审计':'操作审计'),[{label:'时间',value:r=>dateTime(r.event_time)},{label:'用户',value:r=>r.actor_username},{label:'操作',value:r=>actions[r.action]||r.action},{label:'资源',value:r=>r.resource_id},{label:'结果',value:r=>outcomeLabel(r.outcome)},{label:'耗时ms',value:r=>r.duration_ms},{label:'详情',value:r=>r.detail}],filtered.value)}
watch([kind,alertStatus,severity],refresh);watch(()=>props.mode,()=>{search.value='';rows.value=[];detail.value=null;void refresh()});onMounted(refresh);defineExpose({refresh,exportRows});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/>
 <div v-if="mode==='audit'" class="dg-summary"><div><span>近5分钟读取请求</span><strong>{{live?.requests??'—'}}</strong></div><div><span>每秒请求量</span><strong>{{live?.qps??'—'}}</strong></div><div><span>请求失败率</span><strong>{{live?((Number(live.failureRate)*100).toFixed(1)+'%'):'—'}}</strong></div><div><span>成功读取 P95</span><strong>{{live?.p95ReadLatencyMs??'—'}} <small v-if="live?.p95ReadLatencyMs!=null">ms</small></strong></div></div>
 <div v-else class="dg-summary"><div><span>当前列表告警</span><strong>{{rows.length}}</strong></div><div><span>待处理</span><strong>{{rows.filter(r=>r.status==='OPEN').length}}</strong></div><div><span>已确认</span><strong>{{rows.filter(r=>r.status==='ACKNOWLEDGED').length}}</strong></div><div><span>已解决</span><strong>{{rows.filter(r=>r.status==='RESOLVED').length}}</strong></div></div>
 <PagePanel :title="mode==='alerts'?'安全告警':kind?'SQL 请求记录':'操作审计'"><template #actions><template v-if="mode==='audit'"><a-radio-group v-model:value="kind" size="small" button-style="solid"><a-radio-button value="SQL_READ">SQL 请求</a-radio-button><a-radio-button value="">操作审计</a-radio-button></a-radio-group><a-button :disabled="!filtered.length" @click="exportRows"><AppIcon name="export"/>导出记录</a-button></template></template><template #filters><a-input v-model:value="search" allow-clear class="dg-search" :placeholder="mode==='alerts'?'搜索用户、资源或事件':'搜索用户、资源或操作'" aria-label="搜索记录"><template #prefix><AppIcon name="search"/></template></a-input><template v-if="mode==='alerts'"><a-select v-model:value="alertStatus" class="dg-select" aria-label="告警状态" :options="[{value:'',label:'全部状态'},...['OPEN','ACKNOWLEDGED','RESOLVED'].map(value=>({value,label:alertLabels[value]}))]"/><a-select v-model:value="severity" class="dg-select" aria-label="告警等级" :options="[{value:'',label:'全部等级'},...['LOW','MEDIUM','HIGH','CRITICAL'].map(value=>({value,label:alertLabels[value]}))]"/></template><template v-else><a-select v-model:value="outcome" class="dg-select" aria-label="结果" :options="[{value:'all',label:'全部结果'},{value:'SUCCESS',label:'成功'},{value:'DENIED',label:'已拒绝'},{value:'failed',label:'失败'}]"/><div class="dg-date-inputs"><input v-model="from" type="date" aria-label="开始日期" :max="to||undefined"/><span>至</span><input v-model="to" type="date" aria-label="结束日期" :min="from||undefined"/></div><a-button v-if="from||to" type="link" @click="from='';to=''">清除日期</a-button></template></template>
 <a-table v-if="mode==='audit'" :data-source="filtered" :loading="loading" :pagination="pagination" row-key="id" :scroll="{x:900}"><a-table-column title="时间" :width="175"><template #default="{record}">{{dateTime(record.event_time)}}</template></a-table-column><a-table-column title="用户" data-index="actor_username"/><a-table-column v-if="!kind" title="操作"><template #default="{record}">{{actions[record.action]||record.action}}</template></a-table-column><a-table-column title="资源" data-index="resource_id" :ellipsis="true"/><a-table-column title="耗时" :width="100"><template #default="{record}">{{record.duration_ms==null?'—':record.duration_ms+' ms'}}</template></a-table-column><a-table-column title="结果" :width="100"><template #default="{record}"><span class="dg-status" :class="record.outcome==='SUCCESS'?'good':record.outcome==='DENIED'?'warn':'bad'">{{outcomeLabel(record.outcome)}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="90"><template #default="{record}"><a-button type="link" @click="detail=record">详情</a-button></template></a-table-column></a-table>
 <a-table v-else :data-source="filtered" :loading="loading" :pagination="pagination" row-key="id" :scroll="{x:920}"><a-table-column title="时间" :width="175"><template #default="{record}">{{dateTime(record.eventTime)}}</template></a-table-column><a-table-column title="事件"><template #default="{record}">{{alertLabels[record.eventType]||record.eventType}}</template></a-table-column><a-table-column title="等级" :width="80"><template #default="{record}"><span :class="['HIGH','CRITICAL'].includes(record.severity)?'dg-bad-text':'dg-warn-text'">{{alertLabels[record.severity]}}</span></template></a-table-column><a-table-column title="用户" data-index="actor"/><a-table-column title="资源" data-index="resource" :ellipsis="true"/><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="record.status==='OPEN'?'warn':record.status==='RESOLVED'?'good':'off'">{{alertLabels[record.status]}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="140"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" @click="detail=record">详情</a-button><a-button v-if="record.status==='OPEN'" type="link" :disabled="busy" @click="decide(record,'acknowledge')">确认</a-button><a-button v-if="record.status==='ACKNOWLEDGED'" type="link" :disabled="busy" @click="decide(record,'resolve')">解决</a-button></div></template></a-table-column></a-table><template #footer>{{mode==='alerts'?'列表显示筛选结果中最近 100 条告警':'筛选和导出基于最近 200 条已加载记录'}}</template></PagePanel>
 <a-modal :open="!!detail" :title="mode==='alerts'?'告警详情':'审计详情'" centered :width="640" :footer="null" @cancel="detail=null"><a-descriptions v-if="detail" :column="2" layout="vertical"><a-descriptions-item label="时间">{{dateTime(detail.event_time||detail.eventTime)}}</a-descriptions-item><a-descriptions-item label="用户">{{detail.actor_username||detail.actor}}</a-descriptions-item><a-descriptions-item label="事件">{{mode==='alerts'?(alertLabels[detail.eventType]||detail.eventType):(actions[detail.action]||detail.action)}}</a-descriptions-item><a-descriptions-item label="结果">{{mode==='alerts'?alertLabels[detail.status]:outcomeLabel(detail.outcome)}}</a-descriptions-item><a-descriptions-item label="资源" :span="2"><span class="dg-break-text">{{detail.resource_id||detail.resource}}</span></a-descriptions-item><a-descriptions-item label="详情" :span="2"><span class="dg-preserve-lines">{{detail.detail||'—'}}</span></a-descriptions-item><a-descriptions-item v-if="mode==='alerts'" label="确认人">{{detail.acknowledgedBy||'—'}}</a-descriptions-item><a-descriptions-item v-if="mode==='alerts'" label="解决人">{{detail.resolvedBy||'—'}}</a-descriptions-item></a-descriptions><div class="dg-modal-footer"><a-button @click="detail=null">关闭</a-button></div></a-modal>
</template>
